using Microsoft.EntityFrameworkCore; using Veterinaria.Entidades;
namespace Veterinaria.Datos;
public interface IPropietarioRepositorio { Task<List<Propietario>> ListarAsync(); Task<Propietario?> ObtenerAsync(int id); Task<bool> ExisteDniAsync(string dni,int? excluir=null); Task<bool> TieneMascotasAsync(int id); Task AgregarAsync(Propietario x); void Eliminar(Propietario x); Task GuardarAsync(); }
public class PropietarioRepositorio(VeterinariaContext c):IPropietarioRepositorio { public Task<List<Propietario>> ListarAsync()=>c.Propietarios.AsNoTracking().OrderBy(x=>x.Apellidos).ThenBy(x=>x.Nombres).ToListAsync(); public Task<Propietario?> ObtenerAsync(int id)=>c.Propietarios.FirstOrDefaultAsync(x=>x.IdPropietario==id); public Task<bool> ExisteDniAsync(string d,int? e=null)=>c.Propietarios.AnyAsync(x=>x.Dni==d&&(e==null||x.IdPropietario!=e)); public Task<bool> TieneMascotasAsync(int id)=>c.Mascotas.AnyAsync(x=>x.IdPropietario==id); public Task AgregarAsync(Propietario x)=>c.Propietarios.AddAsync(x).AsTask(); public void Eliminar(Propietario x)=>c.Propietarios.Remove(x); public Task GuardarAsync()=>c.SaveChangesAsync(); }
public interface IMascotaRepositorio { Task<List<Mascota>> ListarAsync(string? especie,string? nombre); Task<Mascota?> ObtenerAsync(int id); Task<List<Mascota>> PorPropietarioAsync(int id); Task<bool> PropietarioExisteAsync(int id); Task AgregarAsync(Mascota x); void Eliminar(Mascota x); Task GuardarAsync(); }
public class MascotaRepositorio(VeterinariaContext c):IMascotaRepositorio { public async Task<List<Mascota>> ListarAsync(string? e,string? n){IQueryable<Mascota> q=c.Mascotas.Include(x=>x.Propietario).AsNoTracking();if(!string.IsNullOrWhiteSpace(e))q=q.Where(x=>x.Especie.Contains(e));if(!string.IsNullOrWhiteSpace(n))q=q.Where(x=>x.Nombre.Contains(n));return await q.OrderBy(x=>x.Nombre).ToListAsync();} public Task<Mascota?> ObtenerAsync(int id)=>c.Mascotas.Include(x=>x.Propietario).FirstOrDefaultAsync(x=>x.IdMascota==id); public Task<List<Mascota>> PorPropietarioAsync(int id)=>c.Mascotas.AsNoTracking().Where(x=>x.IdPropietario==id).OrderBy(x=>x.Nombre).ToListAsync(); public Task<bool> PropietarioExisteAsync(int id)=>c.Propietarios.AnyAsync(x=>x.IdPropietario==id); public Task AgregarAsync(Mascota x)=>c.Mascotas.AddAsync(x).AsTask(); public void Eliminar(Mascota x)=>c.Mascotas.Remove(x); public Task GuardarAsync()=>c.SaveChangesAsync(); }
